insert into public.pages (id, slug, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000401', 'home', 'published', '{"title":"Home","seoTitle":"Ever After Memoir — Your day, as it felt","seoDescription":"Wedding content creation and little films by Ever After Memoir. Honest moments, fleeting details and the beautiful in-between.","sections":[{"key":"hero","type":"hero","visible":true,"eyebrow":"Wedding content & little films","headline":"Your day,\n*as it felt.*","body":"Honest moments, fleeting details, and the beautiful in-between — thoughtfully captured, so you can relive the feeling long after the day has passed.","media":{"id":"00000000-0000-4000-8000-000000000001","url":"/samples/hero.jpg","type":"image","alt":"Soft golden light falling across a quiet room (sample image)","width":2400,"height":1350,"poster":null,"isSample":true},"video":{"id":"00000000-0000-4000-8000-000000000028","url":"/samples/hero-loop.mp4","type":"video","alt":"Slow drifting golden light (sample video)","width":1600,"height":900,"poster":"/samples/hero.jpg","isSample":true},"focal":"50% 45%","overlay":0.28,"primary":{"label":"Explore our stories","href":"/stories"},"secondary":{"label":"Let''s talk about your day","href":"/contact"},"showTimecode":true},{"key":"philosophy","type":"philosophy","visible":true,"eyebrow":"What we keep","headline":"Not just how it looked.\n*But how it felt.*","body":"The nervous laughter. The trembling hands. The little glances no one else noticed. We capture the moments that happen between the moments — the ones that make your story entirely yours.","media":{"id":"00000000-0000-4000-8000-000000000002","url":"/samples/philosophy.jpg","type":"image","alt":"Ivory fabric moving in window light (sample image)","width":1200,"height":1500,"poster":null,"isSample":true},"imageSide":"left"},{"key":"marquee","type":"marquee","visible":true,"words":["nervous laughter","trembling hands","quiet glances","happy tears","the in-between"]},{"key":"featured","type":"featured_stories","visible":true,"eyebrow":"Stories","headline":"Days, *remembered.*","body":"A few wedding stories, told the way they felt.","storyIds":[],"link":{"label":"See every story","href":"/stories"}},{"key":"films","type":"films","visible":true,"eyebrow":"Films & reels","headline":"Little films.\n*Lasting feelings.*","body":"Your day unfolds in a thousand little moments. We bring them together in a way that lets you feel it all over again.","film":{"id":"00000000-0000-4000-8000-000000000029","url":"/samples/film.mp4","type":"video","alt":"Sample highlight film","width":1280,"height":720,"poster":"/samples/film-poster.jpg","isSample":true},"poster":{"id":"00000000-0000-4000-8000-000000000023","url":"/samples/film-poster.jpg","type":"image","alt":"Poster frame for the sample film","width":1920,"height":1080,"poster":null,"isSample":true},"filmCaption":"Sample film — replace with your own highlight film","reels":[{"video":{"id":"00000000-0000-4000-8000-000000000030","url":"/samples/reel-1.mp4","type":"video","alt":"Sample vertical reel","width":540,"height":960,"poster":"/samples/reel-1.jpg","isSample":true},"poster":{"id":"00000000-0000-4000-8000-000000000024","url":"/samples/reel-1.jpg","type":"image","alt":"Poster frame for a sample reel","width":720,"height":1280,"poster":null,"isSample":true},"caption":"Getting ready"},{"video":{"id":"00000000-0000-4000-8000-000000000031","url":"/samples/reel-2.mp4","type":"video","alt":"Sample vertical reel","width":540,"height":960,"poster":"/samples/reel-2.jpg","isSample":true},"poster":{"id":"00000000-0000-4000-8000-000000000025","url":"/samples/reel-2.jpg","type":"image","alt":"Poster frame for a sample reel","width":720,"height":1280,"poster":null,"isSample":true},"caption":"First look"},{"video":{"id":"00000000-0000-4000-8000-000000000032","url":"/samples/reel-3.mp4","type":"video","alt":"Sample vertical reel","width":540,"height":960,"poster":"/samples/reel-3.jpg","isSample":true},