insert into public.pages (id, slug, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000402', 'stories', 'published', '{"title":"Stories","seoTitle":"Stories — Ever After Memoir","seoDescription":"Wedding stories by Ever After Memoir — candid moments, quiet details and little films.","sections":[{"key":"intro","type":"page_intro","visible":true,"eyebrow":"Our stories","headline":"Every wedding\n*feels different.*","body":"Some are loud and golden, some are quiet and close. Here are a few, told the way they felt.","media":null},{"key":"grid","type":"stories_grid","visible":true,"showFilters":true},{"key":"cta","type":"cta","visible":true,"headline":"Your story\n*could be next.*","body":"Tell us about your plans and the moments you care about most.","link":{"label":"Let''s talk about your day","href":"/contact"}}]}'::jsonb, '{"title":"Stories","seoTitle":"Stories — Ever After Memoir","seoDescription":"Wedding stories by Ever After Memoir — candid moments, quiet details and little films.","sections":[{"key":"intro","type":"page_intro","visible":true,"eyebrow":"Our stories","headline":"Every wedding\n*feels different.*","body":"Some are loud and golden, some are quiet and close. Here are a few, told the way they felt.","media":null},{"key":"grid","type":"stories_grid","visible":true,"showFilters":true},{"key":"cta","type":"cta","visible":true,"headline":"Your story\n*could be next.*","body":"Tell us about your plans and the moments you care about most.","link":{"label":"Let''s talk about your day","href":"/contact"}}]}'::jsonb, now(), 1) on conflict (slug) do nothing;
insert into public.pages (id, slug, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000403', 'services', 'published', '{"title":"Services","seoTitle":"Services — Ever After Memoir","seoDescription":"Wedding day content, highlight films and personalised coverage by Ever After Memoir.","sections":[{"key":"intro","type":"page_intro","visible":true,"eyebrow":"Services","headline":"Made around\n*your day.*","body":"Every couple remembers different things. Choose what matters most to you, and we will shape the coverage around it.","media":null},{"key":"list","type":"services_list","visible":true,"addonsHeadline":"Little extras","footnote":"Every wedding is different, so every quote is too. Send an inquiry and we will reply with options for your day."},{"key":"cta","type":"cta","visible":true,"headline":"Not sure what\n*you need?*","body":"Tell us about your day and we''ll help you choose.","link":{"label":"Send an inquiry","href":"/contact"}}]}'::jsonb, '{"title":"Services","seoTitle":"Services — Ever After Memoir","seoDescription":"Wedding day content, highlight films and personalised coverage by Ever After Memoir.","sections":[{"key":"intro","type":"page_intro","visible":true,"eyebrow":"Services","headline":"Made around\n*your day.*","body":"Every couple remembers different things. Choose what matters most to you, and we will shape the coverage around it.","media":null},{"key":"list","type":"services_list","visible":true,"addonsHeadline":"Little extras","footnote":"Every wedding is different, so every quote is too. Send an inquiry and we will reply with options for your day."},{"key":"cta","type":"cta","visible":true,"headline":"Not sure what\n*you need?*","body":"Tell us about your day and we''ll help you choose.","link":{"label":"Send an inquiry","href":"/contact"}}]}'::jsonb, now(), 2) on conflict (slug) do nothing;
insert into public.pages (id, slug, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000404', 'about', 'published', '{"title":"About","seoTitle":"About — Ever After Memoir","seoDescription":"Ever After Memoir was created for the moments that deserve to be remembered beyond the photographs.","sections":[{"key":"intro","type":"page_intro","visible":true,"eyebrow":"About","headline":"Behind every memoir,\n*a thousand little feelings.*","body":"Ever After Memoir was created for the moments that deserve to be remembered beyond the photographs — the laughter, the happy tears, the quiet glances, and all the beautiful in-between.","media":{"id":"00000000-0000-4000-8000-000000000013","url":"/samples/about.jpg","type":"image","alt":"Linen in morning light (sample image)","width":1400,"height":1750,"poster":null,"isSample":true}},{"key":"approach","type":"text_image","visible":true,"eyebrow":"How we work","headline":"Close enough to feel it.\n*Quiet enough to miss nothing.*","body":"We stay near the moments that matter and out of the way of the ones that should simply happen.\n\nThe result is content that feels like being there again — the getting ready, the vows, the people you love, and everything in between.","media":{"id":"00000000-0000-4000-8000-000000000002","url":"/samples/philosophy.jpg","type":"image","alt":"Ivory fabric moving in window light (sample image)","width":1200,"height":1500,"poster":null,"isSample":true},"imageSide":"right"},{"key":"founder","type":"founder","visible":false,"eyebrow":"The person behind the camera","headline":"Hello, *I am…*","name":"","role":"","body":"","media":null},{"key":"quote","type":"quote","visible":true,"text":"Your day, as it felt — not just as it looked."},{"key":"cta","type":"cta","visible":true,"headline":"Let''s keep your\n*memories close.*","body":"We would love to hear about your day.","link":{"label":"Let''s create your memoir","href":"/contact"}}]}'::jsonb, '{"title":"About","seoTitle":"About — Ever After Memoir","seoDescription":"Ever After Memoir was created for the moments that deserve to be remembered beyond the photographs.","sections":[{"key":"intro","type":"page_intro","visible":true,"eyebrow":"About","headline":"Behind every memoir,\n*a thousand little feelings.*","body":"Ever After Memoir was created for the moments that deserve to be remembered beyond the photographs — the laughter, the happy tears, the quiet glances, and all the beautiful in-between.","media":{"id":"00000000-0000-4000-8000-000000000013","url":"/samples/about.jpg","type":"image","alt":"Linen in morning light (sample image)","width":1400,"height":1750,"poster":null,"isSample":true}},{"key":"approach","type":"text_image","visible":true,"eyebrow":"How we work","headline":"Close enough to feel it.\n*Quiet enough to miss nothing.*","body":"We stay near the moments that matter and out of the way of the ones that should simply happen.\n\nThe result is content that feels like being there again — the getting ready, the vows, the people you love, and everything in between.","media":{"id":"00000000-0000-4000-8000-000000000002","url":"/samples/philosophy.jpg","type":"image","alt":"Ivory fabric moving in window light (sample image)","width":1200,"height":1500,"poster":null,"isSample":true},"imageSide":"right"},{"key":"founder","type":"founder","visible":false,"eyebrow":"The person behind the camera","headline":"Hello, *I am…*","name":"","role":"","body":"","media":null},{"key":"quote","type":"quote","visible":true,"text":"Your day, as it felt — not just as it looked."},{"key":"cta","type":"cta","visible":true,"headline":"Let''s keep your\n*memories close.*","body":"We would love to hear about your day.","link":{"label":"Let''s create your memoir","href":"/contact"}}]}'::jsonb, now(), 3) on conflict (slug) do nothing;
insert into public.pages (id, slug, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000405', 'contact', 'published', '{"title":"Contact","seoTitle":"Contact — Ever After Memoir","seoDescription":"Tell Ever After Memoir about your wedding day, your plans and the moments you want to remember most.","sections":[{"key":"inquiry","type":"inquiry","visible":true,"headline":"Let''s keep your\n*memories close.*","body":"Tell us a little about your day, your plans, and the moments you want to remember most.","successHeadline":"Thank you — *we have your message.*","successBody":"We read every inquiry personally and will reply to the email you gave us.","privacyNote":"We only use these details to reply to your inquiry and plan your coverage. We never sell or share them."}]}'::jsonb, '{"title":"Contact","seoTitle":"Contact — Ever After Memoir","seoDescription":"Tell Ever After Memoir about your wedding day, your plans and the moments you want to remember most.","sections":[{"key":"inquiry","type":"inquiry","visible":true,"headline":"Let''s keep your\n*memories close.*","body":"Tell us a little about your day, your plans, and the moments you want to remember most.","successHeadline":"Thank you — *we have your message.*","successBody":"We read every inquiry personally and will reply to the email you gave us.","privacyNote":"We only use these details to reply to your inquiry and plan your coverage. We never sell or share them."}]}'::jsonb, now(), 4) on conflict (slug) do nothing;
insert into public.pages (id, slug, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000406', 'privacy', 'published', '{"title":"Privacy","seoTitle":"Privacy policy — Ever After Memoir","seoDescription":"How Ever After Memoir handles the personal details you share with us.","sections":[{"key":"policy","type":"rich_text","visible":true,"headline":"Privacy policy","body":"## What we collect\n\nWhen you send an inquiry, we receive the details you type into the form: your name, your partner’s name, email, WhatsApp number, wedding date, location, the type of celebration, the service you are interested in, an optional budget and any notes.\n\n## Why we collect it\n\nWe use these details only to reply to you, prepare a quote and plan coverage for your wedding.\n\n## Who can see it\n\nYour inquiry is stored securely and is only visible to the Ever After Memoir team. We do not sell, rent or share your details with anyone for marketing.\n\n## How long we keep it\n\nWe keep inquiries for as long as we need them to work with you, and delete closed inquiries we no longer need.\n\n## Your choices\n\nYou can ask us at any time to see, correct or delete the details you sent. Reply to any email from us or send a new inquiry with your request.\n\n## Cookies\n\nThis website does not use advertising or tracking cookies."}]}'::jsonb, '{"title":"Privacy","seoTitle":"Privacy policy — Ever After Memoir","seoDescription":"How Ever After Memoir handles the personal details you share with us.","sections":[{"key":"policy","type":"rich_text","visible":true,"headline":"Privacy policy","body":"## What we collect\n\nWhen you send an inquiry, we receive the details you type into the form: your name, your partner’s name, email, WhatsApp number, wedding date, location, the type of celebration, the service you are interested in, an optional budget and any notes.\n\n## Why we collect it\n\nWe use these details only to reply to you, prepare a quote and plan coverage for your wedding.\n\n## Who can see it\n\nYour inquiry is stored securely and is only visible to the Ever After Memoir team. We do not sell, rent or share your details with anyone for marketing.\n\n## How long we keep it\n\nWe keep inquiries for as long as we need them to work with you, and delete closed inquiries we no longer need.\n\n## Your choices\n\nYou can ask us at any time to see, correct or delete the details you sent. Reply to any email from us or send a new inquiry with your request.\n\n## Cookies\n\nThis website does not use advertising or tracking cookies."}]}'::jsonb, now(), 5) on conflict (slug) do nothing;
insert into public.site_settings (id, status, draft, published, published_at) values ('00000000-0000-4000-8000-000000000901', 'published', '{"siteTitle":"Ever After Memoir","tagline":"Your day, as it felt.","metaDescription":"Ever After Memoir is a wedding content creator capturing honest moments, fleeting details and the beautiful in-between — in photographs, reels and little films.","logo":null,"favicon":null,"ogImage":{"id":"00000000-0000-4000-8000-000000000027","url":"/samples/og.jpg","type":"image","alt":"Ever After Memoir sharing image (sample)","width":1200,"height":630,"poster":null,"isSample":true},"contactEmail":"","whatsappNumber":"","whatsappMessage":"Hi Ever After Memoir, I''d love to ask about my wedding.","instagramUrl":"https://www.instagram.com/everafter.memoir/","tiktokUrl":"https://www.tiktok.com/@everafter.memoir/","footerNote":"Wedding content and little films, made for remembering.","filmGrain":true,"introAnimation":true,"celebrationTypes":["Solemnisation (akad nikah)","Reception (bersanding)","Solemnisation and reception","Engagement","Something else"],"budgetRanges":[],"inquiryRetentionMonths":0}'::jsonb, '{"siteTitle":"Ever After Memoir","tagline":"Your day, as it felt.","metaDescription":"Ever After Memoir is a wedding content creator capturing honest moments, fleeting details and the beautiful in-between — in photographs, reels and little films.","logo":null,"favicon":null,"ogImage":{"id":"00000000-0000-4000-8000-000000000027","url":"/samples/og.jpg","type":"image","alt":"Ever After Memoir sharing image (sample)","width":1200,"height":630,"poster":null,"isSample":true},"contactEmail":"","whatsappNumber":"","whatsappMessage":"Hi Ever After Memoir, I''d love to ask about my wedding.","instagramUrl":"https://www.instagram.com/everafter.memoir/","tiktokUrl":"https://www.tiktok.com/@everafter.memoir/","footerNote":"Wedding content and little films, made for remembering.","filmGrain":true,"introAnimation":true,"celebrationTypes":["Solemnisation 