insert into public.services (id, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000201', 'published', '{"kind":"service","name":"Wedding Day Content","summary":"Candid moments, behind-the-scenes details and the atmosphere of the celebration.","description":"We capture your day as it happens — the getting ready, the in-between, the people around you — as photos and short-form content you can share and keep.","deliverables":[],"price":"","showPrice":false,"priceNote":"","featured":false,"media":{"id":"00000000-0000-4000-8000-000000000014","url":"/samples/service-1.jpg","type":"image","alt":"Sheer fabric in daylight (sample image)","width":1200,"height":1500,"poster":null,"isSample":true}}'::jsonb, '{"kind":"service","name":"Wedding Day Content","summary":"Candid moments, behind-the-scenes details and the atmosphere of the celebration.","description":"We capture your day as it happens — the getting ready, the in-between, the people around you — as photos and short-form content you can share and keep.","deliverables":[],"price":"","showPrice":false,"priceNote":"","featured":false,"media":{"id":"00000000-0000-4000-8000-000000000014","url":"/samples/service-1.jpg","type":"image","alt":"Sheer fabric in daylight (sample image)","width":1200,"height":1500,"poster":null,"isSample":true}}'::jsonb, now(), 0) on conflict (id) do nothing;
